// Des: Attended flow: saved queue pausing only when owner needed
// Flo: create queue (risk class from code sets the approval) > run items in order > needs-you = wait + resume the same item > unsafe = stop the flow > one item failing parks only that item > summary
// I/O: Ctx + routine name or flow id (caller) > item states in the state db; Result counts; restart resumes at the pending item
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const disp = @import("ru-jobs-disp.zig"); const appr = @import("ru-appr-list.zig"); const wait = @import("ru-wait-hand.zig"); const halt = @import("ru-safe-halt.zig"); const flow = @import("ru-flow-runz.zig"); const cfgz = @import("cf-conf-load.zig"); const stat = @import("st-stat-main.zig");
const CF = .{ .tries = 3 };
pub const Result = struct { fid: i64, done: u32 = 0, skip: u32 = 0, fail: u32 = 0, unsure: u32 = 0, state: []const u8 = "done" };
pub fn find(conf: cfgz.Conf, name: []const u8) ?cfgz.FlowDef { for (conf.flow_list) |fl| { if (std.mem.eql(u8, fl.name, name)) return fl; } return null; }
pub fn create(ctx: *task.Ctx, name: []const u8, refs: []const cfgz.JobRef) !i64 { if (refs.len == 0) return error.BadFlow; var elig: usize = 0; for (refs) |rf| { if (rf.acct.len == 0 or std.mem.eql(u8, rf.acct, ctx.acct)) elig += 1; } if (elig == 0) return error.BadFlow; const now = task.nowMs(ctx); const fid = try ctx.store.flowNew(name, now); try ctx.store.flowSet(fid, "plan"); var ix: usize = 0; for (refs) |ref| { if (ref.acct.len > 0 and !std.mem.eql(u8, ref.acct, ctx.acct)) continue; ix += 1; if (!disp.known(ref.job)) return error.NoJob; const txt = try std.json.Stringify.valueAlloc(ctx.aren, ref, .{}); const need = disp.risky(ctx, ref.job, disp.fromRef(ref)); try ctx.store.itemAdd(fid, @intCast(ix), ref.job, txt, if (need) 0 else 1, now); } if (ix == 0) return error.BadFlow; return fid; }
pub fn createNamed(ctx: *task.Ctx, name: []const u8) !i64 { const def = find(ctx.conf, name) orelse return error.BadFlow; return create(ctx, name, def.jobs); }
pub fn openOrNew(ctx: *task.Ctx, name: []const u8) !i64 { const open = try ctx.store.flowOpen(); if (open != 0) { if (try ctx.store.flowGet(ctx.aren, open)) |fl| { if (std.mem.eql(u8, fl.name, name)) return open; } } return createNamed(ctx, name); }
fn finish(ctx: *task.Ctx, fid: i64, res: *Result) void { if (std.mem.eql(u8, res.state, "done")) ctx.store.flowSet(fid, "done") catch {}; const need = res.skip + res.fail + res.unsure; if (need > 0 and std.mem.eql(u8, res.state, "done")) { const msg = (if (std.mem.eql(u8, ctx.conf.lang_main_code, "vi")) std.fmt.allocPrint(ctx.aren, "fb xong: {d} việc đã làm, {d} việc cần bạn xem (fb flow show).", .{ res.done, need }) else std.fmt.allocPrint(ctx.aren, "fb finished: {d} done, {d} need you (fb flow show).", .{ res.done, need })) catch return; wait.notify(ctx, msg); } }
fn mark(ctx: *task.Ctx, id: i64, st: []const u8, info: []const u8) void { ctx.store.itemSet(id, st, info, task.nowMs(ctx)) catch {}; }
pub fn runFlow(ctx: *task.Ctx, fid: i64) !Result { var res: Result = .{ .fid = fid }; if (ctx.mode == .dry or ctx.mode == .read) { const items = try ctx.store.itemList(ctx.aren, fid); for (items) |it| { const ref = try appr.refOf(ctx, it.args); task.say(ctx, "flow item {d}: {s}", .{ it.seq, it.job }); disp.exec(ctx, it.job, disp.fromRef(ref)) catch |err| task.say(ctx, "  preview note: {s}", .{@errorName(err)}); res.done += 1; } return res; } if (!task.consentOk(ctx)) return error.NoConsent; const unt = wait.unsafeUntil(ctx); if (unt > wait.realMs(ctx.iozz)) { task.say(ctx, "cooling down after a safety stop: run fb resume to override", .{}); return error.Unsafe; } try ctx.store.flowSet(fid, "run"); const items = try ctx.store.itemList(ctx.aren, fid); for (items) |it| { if (!(std.mem.eql(u8, it.st, "todo") or std.mem.eql(u8, it.st, "wait") or std.mem.eql(u8, it.st, "doing"))) continue; if (it.appr == 2) { mark(ctx, it.id, "skip", "denied"); res.skip += 1; continue; } if (it.appr == 0 and ctx.mode != .force) { mark(ctx, it.id, "skip", "needs your OK"); res.skip += 1; continue; } mark(ctx, it.id, "doing", ""); const ref = try appr.refOf(ctx, it.args); var tries: u32 = 0; item: while (tries < CF.tries) : (tries += 1) { ctx.approved = true; disp.exec(ctx, it.job, disp.fromRef(ref)) catch |err| { switch (err) { error.Halted, error.NeedLogin => { const kin = flow.peekHalt(ctx.page, ctx.aren) orelse (if (err == error.NeedLogin) halt.Halt.logout else halt.Halt.checkpoint); switch (try wait.handleNeeds(ctx, fid, it.id, kin)) { .resumed => continue :item, .timeout => { res.state = "park"; return res; }, .unsafe => { mark(ctx, it.id, "fail", "unsafe"); res.fail += 1; res.state = "stop"; return res; } } }, error.Unsafe => { wait.stopUnsafe(ctx, fid); mark(ctx, it.id, "fail", "unsafe"); res.fail += 1; res.state = "stop"; return res; }, error.Paused => { ctx.store.flowSet(fid, "park") catch {}; mark(ctx, it.id, "todo", "paused"); res.state = "park"; return res; }, error.Dupe => { mark(ctx, it.id, "unsure", "check Facebook, then fb unlock"); res.unsure += 1; }, error.NoElement, error.Drift => { mark(ctx, it.id, "fail", "page changed: run fb doctor"); res.fail += 1; }, error.CapHit, error.QuietHour, error.NeedApprove => { mark(ctx, it.id, "skip", @errorName(err)); res.skip += 1; }, error.NoConsent => return err, else => { mark(ctx, it.id, "fail", @errorName(err)); res.fail += 1; } } break :item; }; mark(ctx, it.id, "done", ""); res.done += 1; break :item; } } finish(ctx, fid, &res); return res; }
pub fn summary(ctx: *task.Ctx, fid: i64) !void { const flw = (try ctx.store.flowGet(ctx.aren, fid)) orelse return error.BadFlow; const items = try ctx.store.itemList(ctx.aren, fid); task.say(ctx, "flow {d} \"{s}\": {s} · interventions {d} · waited {d} s", .{ flw.id, flw.name, flw.st, flw.ivn, @divFloor(flw.wms, 1000) }); for (items) |it| { const ref = try appr.refOf(ctx, it.args); _ = ref; task.say(ctx, "{d}. {s} [{s}] {s}", .{ it.seq, it.job, it.st, it.info }); } }
